<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { computed } from 'vue'
import { Copy } from 'lucide-vue-next'
import { rmaTypeLabels, rmaOrderTagLabels, type RmaType, type RmaOrder } from '@/api/rma-orders'
import { formatCurrency } from '@/utils/currency'
import OrderProductImage from './OrderProductImage.vue'
import WorkbenchStatusBadge from './WorkbenchStatusBadge.vue'
import OrderAmountBreakdown from '@/components/ui/OrderAmountBreakdown.vue'
const props = defineProps<{ rows: RmaOrder[]; selected: string[]; disabled?: boolean }>()
const emit = defineEmits<{ 'update:selected': [ids: string[]]; copy: [value: string] }>()
const { locale } = useI18n(), zh = computed(() => String(locale.value).startsWith('zh'))
const text = (cn: string, en: string) => zh.value ? cn : en
const afterSaleBills = (row: RmaOrder) => row.rmaCases.filter(flow => Object.hasOwn(rmaTypeLabels, flow.type)).map(flow => ({ ...flow, type: flow.type as RmaType }))
const reasons = (row: RmaOrder) => [...new Set(row.rmaCases.map(flow => flow.reason).filter((reason): reason is string => !!reason))]
const date = (value: string | null) => value && Number.isFinite(Date.parse(value)) ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)) : '—'
function toggle(id: string, event: Event) { emit('update:selected', (event.target as HTMLInputElement).checked ? [...props.selected, id] : props.selected.filter(value => value !== id)) }
</script>
<template>
  <div class="rma-table-wrap"><table class="workbench-task-table rma-table"><thead><tr><th>{{ text('订单编号', 'Order number') }}</th><th>{{ text('商品图片 / 商品信息', 'Product image / details') }}</th><th>{{ text('Shopify 单号', 'Shopify order') }}</th><th>{{ text('订单金额', 'Order amount') }}</th><th>{{ text('退款金额', 'Refund amount') }}</th><th>{{ text('RMA单', 'RMA order') }}</th><th>{{ text('售后原因', 'After-sales reason') }}</th><th>{{ text('客户 / 店铺', 'Customer / store') }}</th><th>{{ text('发货仓库', 'Warehouse') }}</th><th>{{ text('业务员', 'Salesperson') }}</th><th>{{ text('最近更新时间', 'Last updated') }}</th></tr></thead>
    <tbody><tr v-for="row in rows" :key="row.id" class="rma-order-record"><td class="rma-order-number"><div class="rma-order-main"><input type="checkbox" :checked="selected.includes(row.id)" :disabled="disabled" :aria-label="text('选择订单', 'Select order') + ' ' + row.orderNumber" @change="toggle(row.id, $event)"><button class="rma-copy rma-copy-order" :title="row.orderNumber" :aria-label="text('复制订单编号', 'Copy order number') + ' ' + row.orderNumber" @click="emit('copy', row.orderNumber)"><strong>{{ row.orderNumber }}</strong><Copy :size="12" /></button></div><div v-if="row.orderTags?.length" class="rma-order-tags"><WorkbenchStatusBadge v-for="tag in row.orderTags" :key="tag" :tone="tag === 'interception_released' ? 'success' : tag === 'cancellation_requested' ? 'warning' : 'danger'" :title="tag === 'cancellation_requested' ? text('取消申请处理中', 'Cancellation request in progress') : undefined" current>{{ rmaOrderTagLabels[tag][zh ? 0 : 1] }}</WorkbenchStatusBadge></div><small v-if="row.items.length > 1" class="rma-item-summary">{{ text(`${row.items.length} 款商品 · ${row.items.reduce((sum, item) => sum + item.quantity, 0)} 件`, `${row.items.length} products · ${row.items.reduce((sum, item) => sum + item.quantity, 0)} units`) }}</small></td>
      <td class="rma-products" :data-label="text('商品图片 / 商品信息', 'Product image / details')"><div v-for="(item, i) in row.items" :key="i" class="rma-product"><OrderProductImage :src="item.imageUrl" :name="item.name" /><div><span>{{ item.name }}</span><button class="rma-copy" @click="emit('copy', item.sku)"><small>{{ item.sku }}</small><Copy :size="11" /><b>× {{ item.quantity }}</b></button><small>{{ item.variant || '—' }}</small></div></div></td>
      <td class="rma-shopify" :data-label="text('Shopify 单号', 'Shopify order')"><button v-if="row.shopifyOrderNumber" class="rma-copy" @click="emit('copy', row.shopifyOrderNumber)">{{ row.shopifyOrderNumber }}<Copy :size="12" /></button><span v-else>—</span></td>
      <td class="rma-amount" :data-label="text('订单金额', 'Order amount')"><OrderAmountBreakdown :amount="row.amount" :currency="row.currency" :breakdown="row.amountBreakdown" /></td>
      <td class="rma-refund" :data-label="text('退款金额', 'Refund amount')"><template v-if="row.refundAmounts?.length"><div v-for="(refund, i) in row.refundAmounts" :key="i">{{ refund.amount != null && refund.currency ? formatCurrency(refund.amount, refund.currency, String(locale)) : '—' }}</div></template><span v-else>—</span></td>
      <td class="rma-types" :data-label="text('RMA单', 'RMA order')"><div v-for="bill in afterSaleBills(row)" :key="bill.id" class="rma-bill"><span class="rma-bill-type">{{ rmaTypeLabels[bill.type][zh ? 0 : 1] }}</span><button v-if="bill.number" class="rma-copy rma-case-number" :title="bill.number" :aria-label="text('复制售后单号', 'Copy RMA number') + ' ' + bill.number" @click="emit('copy', bill.number)"><span>{{ bill.number }}</span><Copy :size="11" /></button><small v-else>—</small></div><span v-if="!afterSaleBills(row).length">—</span></td>
      <td class="rma-reasons" :data-label="text('售后原因', 'After-sales reason')"><p v-for="reason in reasons(row)" :key="reason" class="rma-reason" :title="reason">{{ reason }}</p><span v-if="!reasons(row).length">—</span></td>
      <td :data-label="text('客户 / 店铺', 'Customer / store')"><button class="rma-copy" @click="emit('copy', row.customerName)">{{ row.customerName }}<Copy :size="11" /></button><small>{{ row.storeName || '—' }}</small></td><td :data-label="text('发货仓库', 'Warehouse')">{{ row.warehouse || '—' }}</td><td :data-label="text('业务员', 'Salesperson')">{{ row.owner?.name || row.salesperson || '—' }}<small>{{ row.department?.name || '—' }}</small></td><td class="rma-date" :data-label="text('最近更新时间', 'Last updated')"><span v-for="(part, i) in date(row.rmaUpdatedAt).split(' ')" :key="i">{{ part }}</span></td></tr></tbody>
  </table></div>
</template>
