ound:var(--color-surface-muted)}.rma-product .rma-copy{margin-top:4px}.rma-product .rma-copy small{margin:0}.rma-order-tags{display:flex;justify-content:center;flex-wrap:wrap;gap:5px;margin-top:8px}.rma-types{font-size:12px;line-height:1.8}.rma-bill+.rma-bill{margin-top:10px}.rma-bill-type{display:block;font-size:12px;font-weight:500}.rma-case-number{font-size:11px;color:var(--color-text-secondary);margin-top:4px;line-height:1.6}.rma-case-number>span{min-width:0;overflow-wrap:anywhere}.rma-reason{font-size:12px;color:var(--color-text-secondary);line-height:1.7;overflow-wrap:anywhere;white-space:pre-wrap;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.rma-reason+.rma-reason{margin-top:8px}.rma-refund{white-space:nowrap;font-variant-numeric:tabular-nums;font-weight:500}.rma-amount{white-space:nowrap;font-variant-numeric:tabular-nums}.rma-date span{display:inline-block;white-space:nowrap}.rma-date span+span{margin-left:4px}
